<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MapleSure SponsorConnect</title>
    <style>
        body { font-family: Arial, sans-serif; padding: 20px; }
        #claim-form, #confirmation { max-width: 600px; margin: auto; }
        #confirmation { display: none; }
        footer { margin-top: 20px; text-align: center; font-size: 0.9em; color: #666; }
        #chosen-files { font-size: 0.9em; color: #333; }
        .hidden { display: none; }
    </style>
    <script>
        document.addEventListener('DOMContentLoaded', function () {
            const mockData = {
                "123-456": { name: "John Doe", dob: "1980-01-01" },
                "789-012": { name: "Jane Smith", dob: "1975-06-15" }
            };

            document.getElementById('lookup-button').onclick = function () {
                const policyNumber = document.getElementById('policy-number').value;
                const memberId = document.getElementById('member-id').value;
                const memberDetails = mockData[memberId];

                if (memberDetails) {
                    document.getElementById('member-details').innerHTML = 
                    `<strong>Name:</strong> ${memberDetails.name}<br><strong>Date of Birth:</strong> ${memberDetails.dob}`;
                } else {
                    document.getElementById('member-details').innerHTML = "Member not found.";
                }
            };

            document.getElementById('documents').onchange = function () {
                const files = document.getElementById('documents').files;
                const fileList = document.getElementById('chosen-files');
                fileList.innerHTML = '';
                for (let i = 0; i < files.length; i++) {
                    fileList.innerHTML += `<li>${files[i].name}</li>`;
                }
            };

            document.getElementById('claim-form').onsubmit = function (event) {
                event.preventDefault();
                const referenceNumber = 'MS-2026-08-' + (Math.floor(Math.random() * 9000) + 1000);
                document.getElementById('claim-form').classList.add('hidden');
                document.getElementById('confirmation').innerHTML = 
                    `<p>Reference Number: ${referenceNumber}</p><p>Status: Received</p>`;
                document.getElementById('confirmation').style.display = 'block';
            };
        });
    </script>
</head>
<body>
    <h1>MapleSure SponsorConnect</h1>
    <form id="claim-form">
        <h2>Member Lookup</h2>
        <label for="policy-number">Policy Number:</label>
        <input type="text" id="policy-number" required><br>

        <label for="member-id">Member ID:</label>
        <input type="text" id="member-id" required><br>

        <button type="button" id="lookup-button">Look up member</button>
        <div id="member-details"></div><br>

        <h2>Claim Details</h2>
        <label for="last-day-worked">Last Day Worked:</label>
        <input type="date" id="last-day-worked" required><br>

        <label for="first-day-absent">First Day Absent:</label>
        <input type="date" id="first-day-absent" required><br>

        <label for="nature-of-absence">Nature of Absence:</label>
        <select id="nature-of-absence">
            <option value="illness">Illness</option>
            <option value="injury">Injury</option>
            <option value="other">Other</option>
        </select><br>

        <label for="details">Details:</label><br>
        <textarea id="details" rows="4" cols="50"></textarea><br>

        <h2>Documents</h2>
        <input type="file" id="documents" multiple><br>
        <ul id="chosen-files"></ul><br>

        <button type="submit">Submit Claim</button>
    </form>

    <div id="confirmation"></div>

    <footer>
        MapleSure Insurance — fictional demo application
    </footer>
</body>
</html>
